}

class Employee {
}

class Manager {
}

class Client {
}

class Account {
  + accountNumber : string
  + balance : double
  + creditLimit : double
  + interestRate : float
  + monthlyFee : float
  + privileges : string[]
}

class MortgageAccount extends Account {
  + propertyCollateral : string
}

class CheckingAccount extends Account {}

class CreditCardAccount extends Account {
  + expiryDate : date
}

class SecondaryCard {}

class JointAccount extends Account {}

Division "1" *-- "*" Subdivision
Division "1" -- "1" Manager
Division "1" -- "*" Employee
Subdivision "1" -- "*" Branch
Branch "1" -- "*" Account
Client "1" -- "*" Account
Client "0..*" -- "0..*" JointAccount
CreditCardAccount "1" *-- "*" SecondaryCard
Client "0..*" -- "0..1" Employee : personal banker

@enduml

